import assert from 'node:assert/strict';import {chromium}from'playwright';import{serveStatic}from'../../engine/static.mjs';
export async function checkProductOrdering(output){let browser,server;try{server=await serveStatic(output);browser=await chromium.launch({channel:'chrome'});const page=await browser.newPage();const bad=[],catalogRequests=[],archiveFetches=[];page.on('request',r=>{if(r.url().includes('/assets/catalogs/'))catalogRequests.push(r.url());if(r.resourceType()==='fetch'&&r.url().includes('/shop/'))archiveFetches.push(r.url());});await page.route('**/*',r=>{if(r.request().method()!=='GET'||new URL(r.request().url()).origin!==server.url){bad.push(r.request().url());return r.abort();}return r.continue();});await page.goto(server.url+'/shop/');const select=page.locator('.woocommerce-ordering select');await select.selectOption('price-desc');await page.waitForFunction(()=>document.querySelector('form.woocommerce-ordering [role=status]')?.textContent.includes('page 1 of 2'));
 assert.deepEqual(await page.locator('ul.products > li h2').allTextContents(),['Locally Authored Bowl','Workshop Shirt']);await page.locator('.migration-pagination a').filter({hasText:/^2$/}).click();await page.waitForFunction(()=>document.querySelector('form.woocommerce-ordering [role=status]')?.textContent.includes('page 2 of 2'));assert.deepEqual(await page.locator('ul.products > li h2').allTextContents(),['Studio Mug']);await page.reload();await page.waitForFunction(()=>document.querySelector('form.woocommerce-ordering [role=status]')?.textContent.includes('page 2 of 2'));assert.deepEqual(await page.locator('ul.products > li h2').allTextContents(),['Studio Mug']);await select.selectOption('price');await page.waitForFunction(()=>document.querySelector('form.woocommerce-ordering [role=status]')?.textContent.includes('page 1 of 2'));assert.deepEqual(await page.locator('ul.products > li h2').allTextContents(),['Studio Mug','Workshop Shirt']);assert.equal(await select.locator('option[value=popularity]').isDisabled(),true);assert.deepEqual(bad,[]);assert.equal(catalogRequests.length,2);assert.deepEqual(archiveFetches,[]);return{sharedManifestRequests:catalogRequests.length,archiveFetches:0,priceSort:true,crossPage:true,reload:true,noExternalRequests:true};}finally{await browser?.close();await server?.close();}}
